<script setup lang="ts">
import { computed, onMounted, onUnmounted, ref, watch } from 'vue'
import { ArrowLeft, ArrowRight, ArrowDown, ArrowUp, BookOpen, CalendarDays, Check, ChevronDown, ChevronRight, Clock3, Compass, Copy, Download, ExternalLink, Flag, FolderPlus, GripVertical, Heart, LayoutGrid, Map, MapPin, Monitor, MoreHorizontal, NotebookPen, Pencil, Plus, RefreshCw, Search, Sparkles, Trash2, Upload, Users, Wallet, X } from '@lucide/vue'
import AppSwitcher from './AppSwitcher.vue'
import PopoverDetails from '@personal/platform/PopoverDetails.vue'
import TravelMap from './travel/TravelMap.vue'
import TravelModal from './travel/TravelModal.vue'
import TripWizard from './travel/TripWizard.vue'
import TripServices from './travel/TripServices.vue'
import { fetchRoadRoute, navigationLink, type RoadRoute } from './travel/services'
import PlaceEditor from './travel/PlaceEditor.vue'
import StopEditor from './travel/StopEditor.vue'
import RouteLibrary from './travel/RouteLibrary.vue'
import MaterialImporter from './travel/MaterialImporter.vue'
import {fetchRoutes,type SavedRoute} from './travel/library'
import './travel-library.css'
import { usePlacesStore, type Place, type PlaceCategory } from './stores/places'
import { useTripsStore, type Trip } from './stores/trips'
import { type CreatePlaceInput } from './api/places'
import { type PlaceCollection, type CollectionInput, fetchCollections, createCollection, updateCollection, deleteCollection } from './api/collections'
import { type TripInput, type TripStopInput, type TripStopRecord, type PlannerDraft, duplicateTrip, importTrip, plannerStatus, draftTrip } from './api/trips'
import { openTripLedgerEntry } from './api/ledgerIntegration'
import { currentUser, travelCacheKey } from './auth'
import { smartLedgerUrl,travelUrl,portalUrl,accountUrl } from './appLinks'
import { categoryColors, dateLabel, daysBetween, exportTrip, hasCoordinates, inspirationTemplates, localDate, money, paceLabels, parseTripFile, preferences, safeSource, scheduleWarnings, stopInput, straightDistance, styles, statusLabels, tripInput } from './travel/model'
import './travel-workspace.css'

const places=usePlacesStore(),trips=useTripsStore()
type View='home'|'planner'|'places'|'routes'|'inspiration'
const view=ref<View>(new URLSearchParams(location.search).has('trip')?'planner':'home')
const selectedTripId=ref(new URLSearchParams(location.search).get('trip')||''),selectedDay=ref(new URLSearchParams(location.search).get('day')||'')
const query=ref(''),tripFilter=ref('all'),placeFilter=ref('all'),placeCategory=ref('all'),cityFilter=ref('all'),placeSort=ref('recent'),libraryMode=ref<'list'|'map'>('list'),selectedPlaceId=ref(''),selectedStopId=ref('')
const loading=ref(true),busy=ref(false),error=ref(''),toast=ref(''),aiAvailable=ref(false)
const materialOpen=ref(false),savedRoutes=ref<SavedRoute[]>([]),routesError=ref('')
async function loadRoutes(){try{savedRoutes.value=await fetchRoutes();routesError.value=''}catch(cause){routesError.value=cause instanceof Error?cause.message:'路线收藏加载失败'}}
async function materialSaved(counts:{places:number;routes:number}){materialOpen.value=false;await Promise.all([places.loadApiPlaces(),loadRoutes()]);navigate(counts.routes?'routes':'places');notify(`已收藏 ${counts.places} 个地点、${counts.routes} 条路线。`)}
const theme=ref<'system'|'light'|'dark'>((()=>{try{const saved=localStorage.getItem('personal-portal-theme');return saved==='light'||saved==='dark'?saved:'system'}catch{return 'system'}})())
const collections=ref<PlaceCollection[]>((()=>{try{const saved=JSON.parse(localStorage.getItem(travelCacheKey('collections'))||'[]');return Array.isArray(saved)?saved.filter(item=>item&&typeof item.id==='string'&&typeof item.name==='string'&&Array.isArray(item.placeIds)):[]}catch{return []}})())
const wizard=ref(false),editingTrip=ref<Trip|null>(null),templateId=ref<string|undefined>()
const placeEditor=ref(false),editingPlace=ref<Place|null>(null),stopEditor=ref(false),editingStop=ref<TripStopRecord|null>(null),initialStopPlace=ref('')
const roadRoute=ref<RoadRoute|null>(null),routeLoading=ref(false),routeError=ref(''),routeMode=ref<'walk'|'drive'>('drive')
const draftTripId=ref('')
const draft=ref<PlannerDraft|null>(null),notesEditor=ref(false),notesText=ref(''),checklistText=ref('')
const collectionEditor=ref(false),editingCollectionId=ref<string|null>(null),collectionForm=ref<CollectionInput>({name:'',description:'',color:'#4d7c76',placeIds:[]})
const importOpen=ref(false),importMode=ref<'trip'|'places'>('trip'),importText=ref(''),importCity=ref(''),importRows=ref<CreatePlaceInput[]>([]),tripImport=ref<ReturnType<typeof parseTripFile>|null>(null)
const dragId=ref<string|null>(null)
let toastTimer:ReturnType<typeof setTimeout>|undefined
const uuid=(id:string)=>/^[0-9a-f]{8}-[0-9a-f]{4}-[1-8][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/i.test(id)
const trip=computed(()=>trips.trips.find(item=>item.id===selectedTripId.value)||null)
const tripDays=computed(()=>daysBetween(trip.value?.startsOn||null,trip.value?.endsOn||null))
const pref=computed(()=>preferences(trip.value))
const travelStyleLabel=computed(()=>pref.value.styles.map(id=>styles.find(item=>item.id===id)?.name).filter(Boolean).join(' · '))
const dayStops=computed(()=>[...(trip.value?.stops||[])].filter(stop=>stop.dayDate===selectedDay.value).sort((a,b)=>a.sortOrder-b.sortOrder))
const dayCost=computed(()=>dayStops.value.reduce((sum,stop)=>sum+Number(stop.estimatedCost||0),0))
const totalCost=computed(()=>(trip.value?.stops||[]).reduce((sum,stop)=>sum+Number(stop.estimatedCost||0),0))
const warnings=computed(()=>scheduleWarnings(dayStops.value))
const selectedPlace=computed(()=>places.places.find(item=>item.id===selectedPlaceId.value)||null)
const cities=computed(()=>[...new Set(places.places.map(place=>place.city))].sort((a,b)=>a.localeCompare(b,'zh-CN')))
const filteredTrips=computed(()=>trips.trips.filter(item=>(tripFilter.value==='all'||item.status===tripFilter.value||(tripFilter.value==='planning'&&item.status==='upcoming'))&&`${item.name} ${item.destination||''}`.toLowerCase().includes(query.value.trim().toLowerCase())))
const filteredPlaces=computed(()=>{
  const selected=collections.value.find(item=>item.id===placeFilter.value)
  const list=places.places.filter(place=>(placeFilter.value==='all'||(placeFilter.value==='favorites'&&place.favorite)||(placeFilter.value==='visited'&&place.visited)||!!selected?.placeIds.includes(place.id))&&(placeCategory.value==='all'||place.category===placeCategory.value)&&(cityFilter.value==='all'||place.city===cityFilter.value)&&`${place.name} ${place.city} ${place.address} ${place.tags.join(' ')} ${place.notes||''}`.toLowerCase().includes(query.value.trim().toLowerCase()))
  if(placeSort.value==='name')list.sort((a,b)=>a.name.localeCompare(b.name,'zh-CN'))
  if(placeSort.value==='city')list.sort((a,b)=>a.city.localeCompare(b.city,'zh-CN'))
  return list
})
const dayPoints=computed(()=>dayStops.value.map((stop,index)=>{const place=places.places.find(item=>item.id===stop.placeId);return place&&hasCoordinates(place)?{id:stop.id,name:stop.placeName,category:stop.category,longitude:place.longitude,latitude:place.latitude,order:index+1}:null}).filter(point=>point!==null))
const plannedCount=computed(()=>trips.trips.filter(item=>['planning','upcoming'].includes(item.status)).length)
const accountName=computed(()=>String(currentUser.value?.profile.name||currentUser.value?.profile.preferred_username||'我的空间'))
const pageTitle=computed(()=>view.value==='planner'?(trip.value?.name||'旅行详情'):view.value==='places'?'地点收藏':view.value==='routes'?'路线收藏':view.value==='inspiration'?'旅行灵感':'我的旅行')

function dismissMenus(event:MouseEvent){const target=event.target as HTMLElement;document.querySelectorAll<HTMLDetailsElement>('.travel-app .tw-menu[open]').forEach(menu=>{if(!menu.contains(target)||!!target.closest('button'))menu.open=false})}
function closeMenusOnEscape(event:KeyboardEvent){if(event.key==='Escape')document.querySelectorAll<HTMLDetailsElement>('.travel-app .tw-menu[open]').forEach(menu=>{menu.open=false})}
function notify(message:string){toast.value=message;if(toastTimer)clearTimeout(toastTimer);toastTimer=setTimeout(()=>{toast.value=''},4000)}
async function perform(work:()=>Promise<void>){if(busy.value)return false;busy.value=true;error.value='';try{await work();return true}catch(cause){error.value=cause instanceof Error?cause.message:'操作未完成，请稍后重试';notify(error.value);return false}finally{busy.value=false}}
function navigate(target:View){view.value=target;query.value='';error.value='';if(target!=='planner')history.replaceState({},'',new URL(travelUrl).pathname)}
function openTrip(item:Trip){selectedTripId.value=item.id;selectedDay.value=item.startsOn||'';selectedStopId.value='';view.value='planner';query.value='';error.value=''}
function createNew(template?:string){templateId.value=template;editingTrip.value=null;error.value='';wizard.value=true}
function editTrip(){if(!trip.value)return;editingTrip.value=trip.value;templateId.value=undefined;error.value='';wizard.value=true}
async function load(){loading.value=true;await Promise.allSettled([places.loadApiPlaces(),trips.loadApiTrips(),loadRoutes(),(async()=>{try{collections.value=await fetchCollections();localStorage.setItem(travelCacheKey('collections'),JSON.stringify(collections.value))}catch{/* Retain account-scoped cached collections. */}})(),(async()=>{try{aiAvailable.value=(await plannerStatus()).aiAvailable}catch{aiAvailable.value=false}})()]);loading.value=false;if(trip.value&&!tripDays.value.includes(selectedDay.value))selectedDay.value=tripDays.value[0]||''}
watch(selectedTripId,()=>{draft.value=null;draftTripId.value=''})
onMounted(()=>{void load();document.addEventListener('click',dismissMenus);document.addEventListener('keydown',closeMenusOnEscape)})
onUnmounted(()=>{document.removeEventListener('click',dismissMenus);document.removeEventListener('keydown',closeMenusOnEscape);if(toastTimer)clearTimeout(toastTimer)})
watch(theme,value=>{try{localStorage.setItem('personal-portal-theme',value)}catch{/* Theme can still change without persistence. */}})
watch([view,selectedTripId,selectedDay],()=>{if(view.value==='planner'&&selectedTripId.value)history.replaceState({},'',new URL(travelUrl).pathname+'?'+new URLSearchParams({trip:selectedTripId.value,...(selectedDay.value?{day:selectedDay.value}:{})}))})
async function saveTrip(input:TripInput,mode:'blank'|'local'|'ai'){
  let generate=false
  const success=await perform(async()=>{
    if(editingTrip.value){const saved=await trips.updateTrip(editingTrip.value.id,input);openTrip(saved)}
    else{const result=await trips.addTrip(input);openTrip(result.trip);generate=result.persisted&&mode!=='blank';notify(result.persisted?'旅行已创建，可以开始安排每一天。':'已保存在本机；连接恢复后编辑可同步到云端。')}
    wizard.value=false
  })
  if(success&&generate)await generateDraft(mode==='ai'?'ai':'local')
}
async function copyTrip(item:Trip){await perform(async()=>{
  if(uuid(item.id)){const copy=await duplicateTrip(item.id);trips.trips.unshift(copy);trips.persist();openTrip(copy)}
  else{const copy=JSON.parse(JSON.stringify(item)) as Trip;copy.id='trip-'+crypto.randomUUID();copy.name=(copy.name+' · 副本').slice(0,180);copy.status='planning';copy.stops=copy.stops.map(stop=>({...stop,id:'stop-'+crypto.randomUUID(),completed:false}));copy.preferences=preferences(copy);copy.preferences.checklist.forEach(check=>{check.done=false});trips.trips.unshift(copy);trips.persist();openTrip(copy)}
  notify('副本已创建，原旅行保持不变。')
})}
async function removeTrip(item:Trip){if(!confirm(`删除“${item.name}”及其日程？关联的记账账本会保留。`))return;await perform(async()=>{await trips.removeTrip(item.id);if(selectedTripId.value===item.id){selectedTripId.value='';navigate('home')}notify('旅行已删除。')})}
async function generateDraft(strategy:'local'|'ai'){
  if(!trip.value)return
  if(!uuid(trip.value.id)){notify('请先连接服务并保存这趟旅行，再生成草稿。');return}
  const id=trip.value.id
  await perform(async()=>{const result=await draftTrip(id,strategy);if(selectedTripId.value===id&&view.value==='planner'){draftTripId.value=id;draft.value=result}})
}
async function applyDraft(){if(!trip.value||!draft.value)return;if(trip.value.id!==draftTripId.value){draft.value=null;notify('草稿属于另一趟旅行，请重新生成。');return}await perform(async()=>{const saved=await trips.saveStops(trip.value!.id,draft.value!.stops);selectedTripId.value=saved.id;selectedDay.value=saved.stops[0]?.dayDate||saved.startsOn||'';draft.value=null;notify('草稿已应用，你可以继续编辑每项安排。')})}
function addStop(placeId=''){if(!trip.value)return;if(!trip.value.startsOn||!trip.value.endsOn){notify('先为旅行设置起止日期，再添加安排。');editTrip();return}editingStop.value=null;initialStopPlace.value=placeId;error.value='';stopEditor.value=true}
function editStop(stop:TripStopRecord){editingStop.value=stop;initialStopPlace.value='';error.value='';stopEditor.value=true}
async function saveStop(input:TripStopInput){if(!trip.value)return;await perform(async()=>{
  const stops=trip.value!.stops.filter(stop=>stop.id!==editingStop.value?.id).map(stopInput)
  const order=editingStop.value?.dayDate===input.dayDate?editingStop.value.sortOrder:stops.filter(stop=>stop.dayDate===input.dayDate).length
  stops.push({...input,id:editingStop.value?.id,sortOrder:order});stops.sort((a,b)=>a.dayDate.localeCompare(b.dayDate)||a.sortOrder-b.sortOrder||a.startsAt.localeCompare(b.startsAt));stops.forEach((stop,index)=>{stop.sortOrder=index})
  const saved=await trips.saveStops(trip.value!.id,stops);selectedTripId.value=saved.id;selectedDay.value=input.dayDate;stopEditor.value=false;notify('安排已保存。')
})}
async function deleteStop(stop:TripStopRecord){if(!trip.value||!confirm(`移除“${stop.placeName}”？`))return;await perform(async()=>{const saved=await trips.saveStops(trip.value!.id,trip.value!.stops.filter(item=>item.id!==stop.id).map((item,index)=>({...stopInput(item),sortOrder:index})));selectedTripId.value=saved.id;notify('安排已移除。')})}
async function toggleStop(stop:TripStopRecord){if(!trip.value)return;await perform(async()=>{const saved=await trips.saveStops(trip.value!.id,trip.value!.stops.map(item=>({...stopInput(item),completed:item.id===stop.id?!item.completed:!!item.completed})));selectedTripId.value=saved.id})}
async function reorder(from:string,to:string){if(!trip.value||from===to||busy.value)return;const list=[...dayStops.value],a=list.findIndex(stop=>stop.id===from),b=list.findIndex(stop=>stop.id===to);if(a<0||b<0)return;const [item]=list.splice(a,1);list.splice(b,0,item!);await perform(async()=>{
  const rest=trip.value!.stops.filter(stop=>stop.dayDate!==selectedDay.value).map(stopInput);list.forEach((stop,index)=>rest.push({...stopInput(stop),sortOrder:index}));const saved=await trips.saveStops(trip.value!.id,rest);selectedTripId.value=saved.id
})}
function moveStop(stop:TripStopRecord,direction:-1|1){const index=dayStops.value.findIndex(item=>item.id===stop.id),target=dayStops.value[index+direction];if(target)void reorder(stop.id,target.id)}
async function alignTimes(){if(!trip.value)return;let clock=9*60;const adjusted=dayStops.value.map(stop=>{const result={...stopInput(stop),startsAt:`${String(Math.floor(clock/60)).padStart(2,'0')}:${String(clock%60).padStart(2,'0')}`};clock+=stop.durationMinutes+30;return result});if(clock-30>1440){notify('当天安排超过一天，请先减少停留时长或移动到其他日期。');return}await perform(async()=>{const saved=await trips.saveStops(trip.value!.id,[...trip.value!.stops.filter(stop=>stop.dayDate!==selectedDay.value).map(stopInput),...adjusted]);selectedTripId.value=saved.id;notify('从 09:00 开始顺排，安排之间预留 30 分钟，可继续修改。')})}
async function saveNotes(){if(!trip.value)return;await perform(async()=>{const saved=await trips.updateTrip(trip.value!.id,{...tripInput(trip.value!),notes:notesText.value});selectedTripId.value=saved.id;notesEditor.value=false;notify('旅行备忘已保存。')})}
async function updateChecklist(id:string|null){if(!trip.value)return;const next=preferences(trip.value);if(id)next.checklist=next.checklist.map(item=>({...item,done:item.id===id?!item.done:item.done}));else{if(!checklistText.value.trim())return;if(next.checklist.length>=80){notify('出行清单最多 80 项。');return}next.checklist.push({id:crypto.randomUUID(),text:checklistText.value.trim(),done:false})}await perform(async()=>{const saved=await trips.updateTrip(trip.value!.id,{...tripInput(trip.value!),preferences:next});selectedTripId.value=saved.id;if(!id)checklistText.value=''})}
async function deleteChecklist(id:string){if(!trip.value)return;await perform(async()=>{const next=preferences(trip.value);next.checklist=next.checklist.filter(item=>item.id!==id);await trips.updateTrip(trip.value!.id,{...tripInput(trip.value!),preferences:next})})}
async function setStatus(status:string){if(!trip.value)return;await perform(async()=>{await trips.updateTrip(trip.value!.id,{...tripInput(trip.value!),status});notify('旅行状态已更新。')})}
async function openLedger(){if(!trip.value)return;await perform(async()=>{let current=trip.value!;if(!uuid(current.id))current=await trips.updateTrip(current.id,tripInput(current));if(!uuid(current.id))throw new Error('旅行账本需要先连接旅游服务并保存行程');selectedTripId.value=current.id;openTripLedgerEntry({id:current.id,name:current.name,destination:current.destination,startsOn:current.startsOn,endsOn:current.endsOn})})}
async function shareTrip(){if(!trip.value)return;const current=trip.value,text=[current.name,`${current.destination||''} ${current.startsOn||''} — ${current.endsOn||''}`,...tripDays.value.flatMap(date=>[dateLabel(date,{month:'long',day:'numeric',weekday:'long'}),...current.stops.filter(stop=>stop.dayDate===date).sort((a,b)=>a.sortOrder-b.sortOrder).map(stop=>`${stop.startsAt} ${stop.placeName}（${stop.durationMinutes}分钟）${stop.note?' · '+stop.note:''}`)])].join('\n');try{await navigator.clipboard.writeText(text);notify('行程文字已复制，可粘贴分享给同行人。')}catch{notify('浏览器未允许复制，可以改用导出行程文件。')}}
function openPlace(place?:Place){editingPlace.value=place||null;error.value='';placeEditor.value=true}
function placeInput(place:Place):CreatePlaceInput{return {name:place.name,city:place.city,address:place.address,category:place.category,tags:place.tags,longitude:place.longitude,latitude:place.latitude,coordinateSystem:place.longitude!=null?'WGS84':null,notes:place.notes||'',sourceUrl:place.sourceUrl||'',favorite:place.favorite,visited:!!place.visited}}
async function savePlace(input:CreatePlaceInput){await perform(async()=>{
  if(editingPlace.value&&uuid(editingPlace.value.id)){const saved=await places.updatePlace(editingPlace.value.id,input);selectedPlaceId.value=saved.id;notify('地点已更新。')}
  else{const oldId=editingPlace.value?.id;const result=await places.addPlace(input.name,input.category,input.city,input.address,input.tags,input);selectedPlaceId.value=result.place.id;if(oldId){await places.deletePlace(oldId);for(const item of trips.trips)for(const stop of item.stops)if(stop.placeId===oldId)stop.placeId=result.place.id;trips.persist()}notify(result.persisted?'地点已收藏并同步到云端。':'地点已保存在本机，服务连接恢复后可编辑同步。')}
  placeEditor.value=false
})}
async function toggleFavorite(place:Place){await perform(async()=>{await places.toggleFavorite(place.id)})}
async function toggleVisited(place:Place){await perform(async()=>{await places.updatePlace(place.id,{...placeInput(place),visited:!place.visited})})}
async function deletePlace(place:Place){if(!confirm(`删除收藏“${place.name}”？已有日程中的文字安排会保留。`))return;await perform(async()=>{await places.deletePlace(place.id);for(const item of trips.trips)for(const stop of item.stops)if(stop.placeId===place.id)stop.placeId=null;trips.persist();collections.value.forEach(item=>{item.placeIds=item.placeIds.filter(id=>id!==place.id)});persistCollections();if(selectedPlaceId.value===place.id)selectedPlaceId.value='';notify('收藏地点已删除。')})}
function openCollection(item?:PlaceCollection){editingCollectionId.value=item?.id||null;collectionForm.value=item?{name:item.name,description:item.description,color:item.color,placeIds:[...item.placeIds]}:{name:'',description:'',color:'#4d7c76',placeIds:[]};error.value='';collectionEditor.value=true}
function persistCollections(){try{localStorage.setItem(travelCacheKey('collections'),JSON.stringify(collections.value))}catch{/* Cloud state remains authoritative. */}}
async function saveCollection(){await perform(async()=>{const saved=editingCollectionId.value?await updateCollection(editingCollectionId.value,collectionForm.value):await createCollection(collectionForm.value);const index=collections.value.findIndex(item=>item.id===saved.id);if(index<0)collections.value.unshift(saved);else collections.value.splice(index,1,saved);persistCollections();collectionEditor.value=false;placeFilter.value=saved.id;notify('合集已保存。')})}
async function removeCollection(item:PlaceCollection){if(!confirm(`删除合集“${item.name}”？其中的收藏地点会保留。`))return;await perform(async()=>{await deleteCollection(item.id);collections.value=collections.value.filter(row=>row.id!==item.id);if(placeFilter.value===item.id)placeFilter.value='all';persistCollections();notify('合集已删除。')})}
async function assignCollection(item:PlaceCollection,place:Place){if(!uuid(place.id)){notify('请先编辑保存这个本地地点，再加入云端合集。');return}await perform(async()=>{const ids=item.placeIds.includes(place.id)?item.placeIds.filter(id=>id!==place.id):[...item.placeIds,place.id];const saved=await updateCollection(item.id,{name:item.name,description:item.description,color:item.color,placeIds:ids});collections.value.splice(collections.value.findIndex(row=>row.id===item.id),1,saved);persistCollections()})}
function startImport(mode:'trip'|'places'){if(mode==='places'){materialOpen.value=true;return}importMode.value=mode;importText.value='';importCity.value='';importRows.value=[];tripImport.value=null;error.value='';importOpen.value=true}
async function readImport(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];if(!file)return;try{if(file.size>2*1024*1024)throw new Error('导入文件需小于 2MB');tripImport.value=parseTripFile(JSON.parse(await file.text()),places.places);error.value=''}catch(cause){error.value=cause instanceof Error?cause.message:'文件读取失败';tripImport.value=null}finally{input.value=''}}
function previewPlaces(){error.value='';try{
  const lines=importText.value.split(/\r?\n/).map(line=>line.trim()).filter(Boolean);if(!lines.length||lines.length>100)throw new Error('每次导入 1 至 100 个地点，一行一个')
  importRows.value=lines.map(line=>{const parts=line.split(/[|\t]/).map(part=>part.trim()),rawName=parts[0]||'';let sourceUrl='',longitude:number|null=null,latitude:number|null=null,name=rawName;if(/^https:\/\//.test(rawName)){const url=new URL(rawName);sourceUrl=safeSource(rawName)||'';const pair=rawName.match(/@(-?\d+(?:\.\d+)?),(-?\d+(?:\.\d+)?)/);latitude=Number(url.searchParams.get('mlat')??pair?.[1]??NaN);longitude=Number(url.searchParams.get('mlon')??pair?.[2]??NaN);if(!/(^|\.)openstreetmap\.org$/.test(url.hostname)&&!/(^|\.)google\.[a-z.]+$/.test(url.hostname)){longitude=null;latitude=null}if(!Number.isFinite(longitude)||!Number.isFinite(latitude)){longitude=null;latitude=null}name=url.searchParams.get('query')||url.searchParams.get('q')||'待填写地点名称'}const category:PlaceCategory=['景点','美食','咖啡','住宿'].includes(parts[2]||'')?parts[2] as PlaceCategory:'景点';return {name:name.slice(0,180),city:(parts[1]||importCity.value).slice(0,120),category,address:(parts[3]||'').slice(0,300),tags:[],sourceUrl,longitude,latitude,coordinateSystem:longitude!=null?'WGS84':null}})
}catch(cause){error.value=cause instanceof Error?cause.message:'清单格式不正确';importRows.value=[]}}
async function applyImport(){await perform(async()=>{if(importMode.value==='trip'){if(!tripImport.value)throw new Error('先选择一个行程文件');const saved=await importTrip(tripImport.value.input,tripImport.value.stops);trips.trips.unshift(saved);trips.persist();openTrip(saved);notify('行程已导入。')}else{if(!importRows.value.length)throw new Error('请先预览地点清单');if(importRows.value.some(item=>!item.name.trim()||!item.city.trim()))throw new Error('每个地点都需要名称和城市');const saved=await places.importPlaces(importRows.value);navigate('places');selectedPlaceId.value=saved[0]?.id||'';notify(`已导入 ${saved.length} 个地点。`)}importOpen.value=false})}
const navigationUrl=computed(()=>dayPoints.value.length===dayStops.value.length?navigationLink(dayPoints.value,pref.value.transport):null)
let routeRequest=0
watch(()=>JSON.stringify([selectedTripId.value,selectedDay.value,dayPoints.value,dayStops.value.map(stop=>[stop.id,stop.sortOrder]),routeMode.value]),()=>{routeRequest++;roadRoute.value=null;routeError.value='';routeLoading.value=false})
async function calculateRoute(){if(!trip.value||routeLoading.value)return;const current=++routeRequest;routeLoading.value=true;routeError.value='';try{const result=await fetchRoadRoute(trip.value.id,selectedDay.value,routeMode.value);if(current===routeRequest)roadRoute.value=result}catch(cause){if(current===routeRequest)routeError.value=cause instanceof Error?cause.message:'路线查询失败'}finally{if(current===routeRequest)routeLoading.value=false}}
function selectMapStop(id:string){selectedStopId.value=id;document.getElementById('tw-stop-'+id)?.scrollIntoView({block:'nearest',behavior:'smooth'})}
function showDayMap(){document.getElementById('tw-day-map')?.scrollIntoView({block:'start',behavior:'smooth'})}
function countdown(item:Trip){if(!item.startsOn)return '日期待定';const days=Math.round((new Date(item.startsOn+'T12:00:00').getTime()-new Date(localDate()+'T12:00:00').getTime())/86400000);return days>0?`还有 ${days} 天`:days===0?'今天出发':item.status==='completed'?'旅程已完成':'已到出行日期'}
function coverTone(item:Trip,index:number){const primary=preferences(item).styles[0];return primary==='nature'?'green':primary==='food'?'peach':primary==='family'?'sand':['blue','green','peach','sand'][index%4]}
function legNavigation(index:number){const from=places.places.find(place=>place.id===dayStops.value[index]?.placeId),to=places.places.find(place=>place.id===dayStops.value[index+1]?.placeId);return from&&to?navigationLink([from,to],pref.value.transport):null}
function transitionLabel(index:number){const a=places.places.find(place=>place.id===dayStops.value[index]?.placeId),b=places.places.find(place=>place.id===dayStops.value[index+1]?.placeId);if(!a||!b)return '交通待安排';const road=roadRoute.value?.legs[index];if(road)return `道路 ${(road.distance/1000).toFixed(1)} km · 约 ${Math.ceil(road.duration/60)} 分钟（不含实时路况）`;const distance=straightDistance(a,b);return distance==null?'交通待安排':`直线 ${distance<1?Math.round(distance*1000)+' m':distance.toFixed(1)+' km'} · 请核对实际路线`}
</script>

<template>
<div class="travel-app" :class="'tw-theme-'+theme">
  <aside class="tw-sidebar"><a class="tw-brand" href="/travel/" @click.prevent="navigate('home')"><span><Compass :size="23"/></span><b>WhereToGo<small>YOUR TRAVEL SPACE</small></b></a><span class="tw-nav-label">你的旅行空间</span><nav aria-label="旅游导航"><button :class="{active:view==='home'||view==='planner'}" @click="navigate('home')"><CalendarDays :size="19"/>我的旅行<span>{{ trips.trips.length }}</span></button><button :class="{active:view==='places'}" @click="navigate('places')"><MapPin :size="19"/>地点收藏<span>{{ places.places.length }}</span></button><button :class="{active:view==='routes'}" @click="navigate('routes')"><Compass :size="19"/>路线收藏<span>{{ savedRoutes.length }}</span></button><button :class="{active:view==='inspiration'}" @click="navigate('inspiration')"><Sparkles :size="19"/>旅行灵感</button></nav><div class="tw-sidebar-note"><Compass :size="25"/><b>下一段故事，从这里开始。</b><p>收藏灵感，安排每一天。<br/>给未知留一点位置。</p><button @click="createNew()">计划一趟旅行 <Plus :size="14"/></button></div><footer><a :href="portalUrl">← 返回个人门户</a><a href="/system/">API 与服务状态</a><a :href="smartLedgerUrl"><Wallet :size="15"/>打开 SmartLedger</a><button class="tw-connection" :disabled="loading" @click="load"><i :class="{online:places.apiConnected&&trips.apiConnected}"></i>{{ places.apiConnected&&trips.apiConnected?'已连接云端':'查看本机缓存' }}<RefreshCw :size="12" :class="{spinning:loading}"/></button></footer></aside>
  <div class="tw-main"><header class="tw-topbar"><div class="tw-breadcrumb"><Compass :size="15"/><button @click="navigate('home')">旅行空间</button><ChevronRight :size="12"/><span>{{ pageTitle }}</span></div><div class="tw-topbar-actions"><label class="tw-theme-control"><Monitor :size="15"/><select v-model="theme" aria-label="旅游应用外观"><option value="system">跟随系统</option><option value="light">浅色</option><option value="dark">夜间</option></select></label><AppSwitcher current="travel"/><a :href="accountUrl" class="tw-account" :title="accountName"><span>{{ accountName.slice(0,1) }}</span><b>{{ accountName }}</b></a></div></header>
    <main class="tw-content" :class="{'tw-planner-content':view==='planner'}">
      <p v-if="error&&!wizard&&!placeEditor&&!stopEditor&&!draft&&!notesEditor&&!collectionEditor&&!importOpen" class="tw-page-error" role="alert">{{ error }}<button @click="error=''" aria-label="关闭错误"><X :size="14"/></button></p>
      <template v-if="view==='home'">
        <section class="tw-hero"><div><span class="tw-kicker">MAKE ROOM FOR THE JOURNEY</span><h1>下一站，去哪里？</h1><p>把想去的地方，安排成值得期待的每一天。</p><div class="tw-hero-actions"><button class="tw-button primary" @click="createNew()"><Plus :size="17"/>计划新旅行</button><button class="tw-button secondary" @click="materialOpen=true"><Upload :size="15"/>导入旅行灵感</button></div></div><div class="tw-hero-art" aria-hidden="true"><span class="tw-orbit one"></span><span class="tw-orbit two"></span><i class="tw-art-pin"><MapPin :size="35"/></i><i class="tw-art-route"><Compass :size="21"/></i><span class="tw-art-label">THE NEXT CHAPTER</span></div></section>
        <div class="tw-stats"><span><CalendarDays :size="18"/><b>{{ trips.trips.length }}</b>趟旅行</span><span><Flag :size="18"/><b>{{ plannedCount }}</b>趟期待中的旅程</span><span><MapPin :size="18"/><b>{{ places.places.length }}</b>个想去的地点</span><button class="tw-text" @click="startImport('trip')"><Upload :size="14"/>导入行程</button></div>
        <section class="tw-trips-section"><header class="tw-section-heading"><div><h2>我的旅行</h2><p>正在计划的，和已经走过的。</p></div><label class="tw-search"><Search :size="16"/><input v-model="query" aria-label="搜索旅行" placeholder="搜索旅行或目的地"/></label></header><div class="tw-tabs" role="group" aria-label="旅行状态"><button v-for="tab in [{id:'all',name:'全部旅行'},{id:'planning',name:'计划中'},{id:'ongoing',name:'进行中'},{id:'completed',name:'已完成'}]" :key="tab.id" :class="{active:tripFilter===tab.id}" @click="tripFilter=tab.id">{{ tab.name }}</button></div>
          <div v-if="loading&&!trips.trips.length" class="tw-empty"><RefreshCw class="spinning" :size="24"/><h3>正在准备旅行空间</h3></div>
          <div v-else-if="filteredTrips.length" class="tw-trip-grid"><article v-for="(item,index) in filteredTrips" :key="item.id" class="tw-trip-card"><button class="tw-trip-cover" :class="'tone-'+coverTone(item,index)" @click="openTrip(item)"><svg viewBox="0 0 400 180" aria-hidden="true"><path d="M-30 155 100 35 210 140 285 64 450 175V230H-30Z"/><path d="M-30 180 150 90 260 170 400 112 450 175V230H-30Z"/><circle cx="315" cy="39" r="23"/></svg><span class="tw-trip-status">{{ statusLabels[item.status]||'计划中' }}</span><small>{{ (item.destination||'下一站').slice(0,18) }}</small><span class="tw-cover-caption">{{ countdown(item) }}</span></button><div class="tw-trip-card-body"><div class="tw-card-title"><button @click="openTrip(item)"><h3>{{ item.name }}</h3></button><PopoverDetails class="tw-menu"><template #trigger><summary aria-label="旅行操作"><MoreHorizontal :size="19"/></summary></template><button :disabled="busy" @click="copyTrip(item)"><Copy :size="14"/>创建副本</button><button @click="exportTrip(item,'html')"><Download :size="14"/>导出行程单</button><button @click="exportTrip(item,'json')"><Download :size="14"/>导出 JSON</button><button :disabled="busy" class="danger" @click="removeTrip(item)"><Trash2 :size="14"/>删除旅行</button></PopoverDetails></div><p><CalendarDays :size="13"/>{{ dateLabel(item.startsOn) }} — {{ dateLabel(item.endsOn) }}</p><div class="tw-card-meta"><span>{{ daysBetween(item.startsOn,item.endsOn).length||'待定' }} 天</span><i></i><span>{{ item.stops.length }} 项安排</span><i></i><span>{{ preferences(item).travelers }} 人同行</span></div><footer><span>{{ preferences(item).budgetAmount?`预算 ${money(preferences(item).budgetAmount)}`:'让期待慢慢成形' }}</span><button @click="openTrip(item)">打开行程<ArrowRight :size="15"/></button></footer></div></article><button class="tw-new-trip-card" @click="createNew()"><span><Plus :size="27"/></span><b>下一趟旅行</b><small>从一个目的地开始</small></button></div>
          <div v-else class="tw-empty"><Compass :size="34"/><h3>{{ trips.trips.length?'没有找到这趟旅行':'你的下一段故事，还没开始。' }}</h3><p>{{ trips.trips.length?'试试其他状态或目的地关键词。':'选一个想去的地方，留下属于你的旅行计划。' }}</p><button class="tw-button primary" @click="createNew()"><Plus :size="15"/>创建一趟旅行</button></div>
        </section>
      </template>

      <template v-else-if="view==='planner'&&trip">
        <div class="tw-planner-heading"><div><button class="tw-back" @click="navigate('home')"><ArrowLeft :size="14"/>我的旅行</button><h1>{{ trip.name }}<span>{{ statusLabels[trip.status]||'计划中' }}</span></h1><p><MapPin :size="14"/>{{ trip.destination||'目的地待定' }}<i>·</i><CalendarDays :size="14"/>{{ dateLabel(trip.startsOn) }} — {{ dateLabel(trip.endsOn) }}<i>·</i><Users :size="14"/>{{ pref.travelers }} 人</p></div><div class="tw-planner-tools"><button class="tw-button secondary" :disabled="busy" @click="editTrip"><Pencil :size="14"/>旅行设置</button><PopoverDetails class="tw-menu"><template #trigger><summary class="tw-button secondary"><Download :size="14"/>导出与分享<ChevronDown :size="12"/></summary></template><button @click="shareTrip"><Copy :size="14"/>复制行程文字</button><button @click="exportTrip(trip,'html')">可打印行程单</button><button @click="exportTrip(trip,'json')">JSON 备份</button><button @click="exportTrip(trip,'ics')">日历文件（本地时间）</button></PopoverDetails></div></div>
        <section class="tw-trip-overview"><div><span class="tw-overview-icon"><CalendarDays :size="19"/></span><span><small>旅行长度</small><b>{{ tripDays.length||'待定' }} <em>天</em></b></span></div><div><span class="tw-overview-icon"><Check :size="19"/></span><span><small>已完成安排</small><b>{{ trip.stops.filter(stop=>stop.completed).length }} <em>/ {{ trip.stops.length }}</em></b></span></div><div><span class="tw-overview-icon"><Wallet :size="19"/></span><span><small>计划费用 / 总预算</small><b>{{ money(totalCost) }} <em>/ {{ pref.budgetAmount?money(pref.budgetAmount):'待设置' }}</em></b></span></div><button class="tw-ledger-link" :disabled="busy" @click="openLedger"><BookOpen :size="19"/><span><b>旅行账本</b><small>在 SmartLedger 记录实际花费</small></span><ArrowRight :size="17"/></button></section>
        <div v-if="pref.budgetAmount&&totalCost>pref.budgetAmount" class="tw-warning">计划费用比预算多 {{ money(totalCost-pref.budgetAmount) }}，可调整安排或修改预算。</div>
        <button class="tw-mobile-map-link tw-button secondary" @click="showDayMap"><Map :size="15"/>查看当天地图</button><div class="tw-planner-layout"><section class="tw-itinerary-panel"><div class="tw-itinerary-toolbar"><div class="tw-day-tabs"><button v-for="(date,index) in tripDays" :key="date" :class="{active:selectedDay===date}" @click="selectedDay=date;selectedStopId=''">DAY {{ String(index+1).padStart(2,'0') }}<small>{{ dateLabel(date,{month:'numeric',day:'numeric'}) }}</small></button></div><PopoverDetails class="tw-menu tw-plan-menu"><template #trigger><summary class="tw-button soft" :aria-disabled="busy"><Sparkles :size="15"/>智能编排<ChevronDown :size="12"/></summary></template><button :disabled="busy" @click="generateDraft('local')">从收藏生成草稿</button><button :disabled="busy||!aiAvailable" @click="generateDraft('ai')">{{ aiAvailable?'使用外部 AI':'AI 服务未配置' }}</button><small v-if="aiAvailable" class="tw-ai-disclosure">将本次旅行（含备注、清单、已有安排）及相关收藏发送给已配置的 AI 服务。</small></PopoverDetails></div>
          <header class="tw-day-heading"><div><span class="tw-kicker">DAY {{ Math.max(1,tripDays.indexOf(selectedDay)+1) }}</span><h2>{{ dateLabel(selectedDay,{month:'long',day:'numeric',weekday:'long'}) }}</h2><p>{{ dayStops.length }} 项安排 · 计划 {{ money(dayCost) }}</p></div><button class="tw-text" :disabled="busy||!dayStops.length" @click="alignTimes"><Clock3 :size="14"/>顺排时间</button></header>
          <div v-if="warnings.length" class="tw-warning"><b>时间需要留意</b><p v-for="warning in warnings" :key="warning">{{ warning }}</p></div>
          <div class="tw-timeline"><template v-for="(stop,index) in dayStops" :key="stop.id"><article :id="'tw-stop-'+stop.id" class="tw-stop" :class="{completed:stop.completed,selected:selectedStopId===stop.id}" draggable="true" @dragstart="dragId=stop.id" @dragend="dragId=null" @dragover.prevent @drop.prevent="{if(dragId)reorder(dragId,stop.id);dragId=null}"><div class="tw-stop-number" :style="{'--category-color':categoryColors[stop.category]||'#7a8b91'}">{{ index+1 }}</div><div class="tw-stop-main"><header><span class="tw-stop-time">{{ stop.startsAt }}</span><span class="tw-stop-type">{{ stop.category }}</span><span class="tw-stop-duration"><Clock3 :size="12"/>{{ stop.durationMinutes }} 分钟</span><PopoverDetails class="tw-menu"><template #trigger><summary aria-label="日程操作"><MoreHorizontal :size="18"/></summary></template><button :disabled="busy" @click="editStop(stop)"><Pencil :size="14"/>编辑安排</button><button :disabled="busy||index===0" @click="moveStop(stop,-1)"><ArrowUp :size="14"/>向前移动</button><button :disabled="busy||index===dayStops.length-1" @click="moveStop(stop,1)"><ArrowDown :size="14"/>向后移动</button><button :disabled="busy" class="danger" @click="deleteStop(stop)"><Trash2 :size="14"/>移除安排</button></PopoverDetails></header><button class="tw-stop-name" @click="selectedStopId=stop.id">{{ stop.placeName }}</button><p v-if="stop.note" class="tw-stop-note">{{ stop.note }}</p><footer><span>{{ stop.estimatedCost?money(Number(stop.estimatedCost)):'费用待填写' }}</span><button class="tw-text" :disabled="busy" @click="editStop(stop)">编辑</button><button class="tw-stop-check" :class="{done:stop.completed}" :disabled="busy" @click="toggleStop(stop)"><Check :size="12"/>{{ stop.completed?'已完成':'标记完成' }}</button><GripVertical class="tw-drag-grip" :size="15" aria-label="可拖动排序"/></footer></div></article><div v-if="index<dayStops.length-1" class="tw-transfer"><span></span><MapPin :size="11"/>{{ transitionLabel(index) }}<a v-if="legNavigation(index)" :href="legNavigation(index)!" target="_blank" rel="noopener noreferrer">导航<ExternalLink :size="10"/></a></div></template><div v-if="!dayStops.length" class="tw-day-empty"><MapPin :size="28"/><h3>给这一天，留点期待。</h3><p>从收藏添加地点，也可以自行填写交通和活动。</p></div><button class="tw-add-stop" :disabled="busy" @click="addStop()"><Plus :size="17"/>添加地点或活动</button></div>
          <section class="tw-trip-notes"><header><h3><NotebookPen :size="17"/>旅行备忘</h3><button class="tw-text" @click="notesText=trip.notes||'';error='';notesEditor=true">{{ trip.notes?'编辑':'写一点备忘' }}</button></header><p>{{ trip.notes||'预约、交通、行李或临时想到的事，都记在这里。' }}</p></section>
          <section class="tw-checklist"><header><h3><Check :size="17"/>出行清单</h3><span>{{ pref.checklist.filter(item=>item.done).length }} / {{ pref.checklist.length }}</span></header><div v-for="item in pref.checklist" :key="item.id" class="tw-checklist-row"><button :class="{done:item.done}" :disabled="busy" @click="updateChecklist(item.id)"><i><Check v-if="item.done" :size="12"/></i><span>{{ item.text }}</span></button><button class="tw-icon" :disabled="busy" aria-label="删除清单项" @click="deleteChecklist(item.id)"><X :size="13"/></button></div><form class="tw-checklist-add" @submit.prevent="updateChecklist(null)"><input v-model="checklistText" maxlength="180" placeholder="还有什么需要准备？" aria-label="新增出行清单项"/><button class="tw-icon" :disabled="busy||!checklistText.trim()" aria-label="添加清单项"><Plus :size="17"/></button></form></section>
        </section><aside id="tw-day-map" class="tw-planner-aside"><section class="tw-map-panel"><header><h3><Map :size="16"/>这一天，去哪里</h3><span>{{ dayPoints.length }} 个已定位</span></header><TravelMap :points="dayPoints" route :road="roadRoute?.geometry.coordinates" :selected="selectedStopId" @select="selectMapStop"/><div class="tw-route-controls"><select v-model="routeMode" aria-label="道路路线方式"><option value="drive">驾车道路</option><option value="walk">步行道路</option></select><button class="tw-button secondary" :disabled="routeLoading||dayPoints.length<2||dayPoints.length!==dayStops.length||dayPoints.length>25" @click="calculateRoute">{{ routeLoading?'计算中…':'查询道路路线' }}</button><a v-if="navigationUrl" :href="navigationUrl" target="_blank" rel="noopener noreferrer" class="tw-text">打开外部导航<ExternalLink :size="12"/></a><p v-if="roadRoute">道路约 {{ (roadRoute.distance/1000).toFixed(1) }} km · {{ Math.ceil(roadRoute.duration/60) }} 分钟；非实时路况，不含停留和交通等待。</p><p v-if="routeError" class="tw-error" role="alert">{{ routeError }}</p><small>点击查询会将当天已定位的路线点位发送给 FOSSGIS/OSRM。<a href="https://routing.openstreetmap.de/about.html" target="_blank" rel="noopener noreferrer">服务说明</a> · <a href="https://www.openstreetmap.org/fixthemap" target="_blank" rel="noopener noreferrer">修正地图</a></small></div><footer v-if="dayPoints.length<dayStops.length">{{ dayStops.length-dayPoints.length }} 项未关联已定位地点，可编辑后从收藏中选择。</footer><footer v-else-if="!dayPoints.length">为收藏地点补充坐标后，安排会显示在地图上。</footer></section><section class="tw-compact-card"><span class="tw-kicker">YOUR WAY OF TRAVEL</span><h3>{{ paceLabels[pref.pace] }}，也很好。</h3><p>{{ travelStyleLabel||'按自己的方式，慢慢填上每一天。' }}</p><button class="tw-text" @click="editTrip">调整偏好<ArrowRight :size="13"/></button></section><section class="tw-compact-card"><header><h3>行程状态</h3><select :value="trip.status" aria-label="行程状态" :disabled="busy" @change="setStatus(($event.target as HTMLSelectElement).value)"><option value="planning">计划中</option><option value="ongoing">进行中</option><option value="completed">已完成</option></select></header><p>完成一趟旅行，也留住这一段记忆。</p></section><TripServices :key="trip.id" :trip="trip" :day="selectedDay"/></aside></div>
      </template>
      <div v-else-if="view==='planner'" class="tw-empty"><Compass :size="32"/><h2>{{ loading?'正在打开行程':'没有找到这趟旅行' }}</h2><p>旅行按账号保存，请确认当前账号和行程链接。</p><button class="tw-button secondary" @click="navigate('home')">返回我的旅行</button></div>

      <template v-else-if="view==='places'"><header class="tw-section-heading tw-page-heading"><div><span class="tw-kicker">SAVE NOW, GO LATER</span><h1>收藏下一次心动。</h1><p>餐馆、展馆、咖啡店，或还没走过的山野。</p></div><div class="tw-heading-actions"><button class="tw-button secondary" @click="startImport('places')"><Upload :size="15"/>导入清单</button><button class="tw-button primary" @click="openPlace()"><Plus :size="16"/>收藏地点</button></div></header>
        <div class="tw-collections"><button :class="{active:placeFilter==='all'}" @click="placeFilter='all'">全部地点<span>{{ places.places.length }}</span></button><button :class="{active:placeFilter==='favorites'}" @click="placeFilter='favorites'"><Heart :size="13"/>特别想去</button><button :class="{active:placeFilter==='visited'}" @click="placeFilter='visited'"><Check :size="13"/>去过的地方</button><div v-for="item in collections" :key="item.id" class="tw-collection-chip"><button :class="{active:placeFilter===item.id}" @click="placeFilter=item.id"><i :style="{background:item.color}"></i>{{ item.name }}<span>{{ item.placeIds.length }}</span></button><PopoverDetails class="tw-menu"><template #trigger><summary :aria-label="item.name+'合集操作'"><MoreHorizontal :size="13"/></summary></template><button @click="openCollection(item)">编辑合集</button><button class="danger" :disabled="busy" @click="removeCollection(item)">删除合集</button></PopoverDetails></div><button class="tw-new-collection" @click="openCollection()"><FolderPlus :size="14"/>新建合集</button></div>
        <div class="tw-library-toolbar"><label class="tw-search"><Search :size="15"/><input v-model="query" placeholder="名称、城市或标签" aria-label="搜索收藏地点"/></label><select v-model="cityFilter" aria-label="筛选城市"><option value="all">所有城市</option><option v-for="city in cities" :key="city">{{ city }}</option></select><select v-model="placeCategory" aria-label="筛选分类"><option value="all">所有分类</option><option v-for="category in ['景点','美食','咖啡','住宿']" :key="category">{{ category }}</option></select><select v-model="placeSort" aria-label="地点排序"><option value="recent">最近收藏</option><option value="name">按名称</option><option value="city">按城市</option></select><div class="tw-view-toggle"><button :class="{active:libraryMode==='list'}" @click="libraryMode='list'" aria-label="地点列表"><LayoutGrid :size="16"/></button><button :class="{active:libraryMode==='map'}" @click="libraryMode='map'" aria-label="地点地图"><Map :size="16"/></button></div></div>
        <div class="tw-library-layout" :class="{'show-map':libraryMode==='map'}"><div class="tw-place-grid"><article v-for="place in filteredPlaces" :key="place.id" class="tw-place-card" :class="{selected:selectedPlaceId===place.id}"><button class="tw-place-card-main" @click="selectedPlaceId=place.id;libraryMode='map'"><span class="tw-place-category" :style="{'--category-color':categoryColors[place.category]}"><MapPin :size="22"/></span><span class="tw-place-card-title"><small>{{ place.city }} · {{ place.category }}</small><h3>{{ place.name }}</h3></span><ChevronRight :size="16"/></button><p>{{ place.address||'地址待补充' }}</p><div class="tw-place-tags"><span v-for="tag in place.tags.slice(0,3)" :key="tag">{{ tag }}</span><span v-if="!hasCoordinates(place)" class="pending">待定位</span></div><footer><button class="tw-favorite" :class="{active:place.favorite}" :disabled="busy" :aria-label="place.favorite?'取消特别想去':'标记特别想去'" @click="toggleFavorite(place)"><Heart :size="15" :fill="place.favorite?'currentColor':'none'"/></button><button class="tw-text" :disabled="busy" @click="toggleVisited(place)"><Check :size="13"/>{{ place.visited?'已去过':'标记去过' }}</button><button class="tw-text" @click="openPlace(place)">编辑</button></footer></article><div v-if="!filteredPlaces.length" class="tw-empty"><MapPin :size="30"/><h3>还没有匹配的收藏</h3><p>先收下一个想去的地方吧。</p><button class="tw-button primary" @click="openPlace()">收藏地点</button></div></div><aside class="tw-library-map"><TravelMap :points="filteredPlaces" :selected="selectedPlaceId" @select="selectedPlaceId=$event"/><section v-if="selectedPlace" class="tw-selected-place"><div><span class="tw-kicker">{{ selectedPlace.city }} · {{ selectedPlace.category }}</span><h3>{{ selectedPlace.name }}</h3><p>{{ selectedPlace.address||'地址待补充' }}</p><p v-if="selectedPlace.notes" class="tw-selected-note">{{ selectedPlace.notes }}</p></div><div class="tw-selected-actions"><button class="tw-button secondary" @click="openPlace(selectedPlace)"><Pencil :size="13"/>编辑地点</button><a v-if="safeSource(selectedPlace.sourceUrl)" class="tw-button secondary" :href="safeSource(selectedPlace.sourceUrl)!" target="_blank" rel="noopener noreferrer">查看来源<ExternalLink :size="12"/></a><a v-if="hasCoordinates(selectedPlace)" class="tw-button secondary" :href="'https://www.openstreetmap.org/?mlat='+selectedPlace.latitude+'&mlon='+selectedPlace.longitude+'#map=16/'+selectedPlace.latitude+'/'+selectedPlace.longitude" target="_blank" rel="noopener noreferrer">打开地图<ExternalLink :size="12"/></a><button class="tw-icon danger" :disabled="busy" aria-label="删除收藏地点" @click="deletePlace(selectedPlace)"><Trash2 :size="16"/></button></div><div v-if="collections.length" class="tw-place-assign"><span>加入合集</span><button v-for="item in collections" :key="item.id" :class="{active:item.placeIds.includes(selectedPlace.id)}" :disabled="busy" @click="assignCollection(item,selectedPlace)"><Check v-if="item.placeIds.includes(selectedPlace.id)" :size="12"/>{{ item.name }}</button></div><div v-if="trips.trips.length" class="tw-place-to-trip"><label>加入旅行<select :value="''" :disabled="busy" @change="event=>{const found=trips.trips.find(item=>item.id===(event.target as HTMLSelectElement).value);if(found){openTrip(found);addStop(selectedPlace!.id)}}"><option value="" disabled>选择一趟旅行</option><option v-for="item in trips.trips" :key="item.id" :value="item.id">{{ item.name }}</option></select></label></div></section><p class="tw-map-help">只展示有真实坐标的收藏 · {{ filteredPlaces.filter(hasCoordinates).length }} / {{ filteredPlaces.length }} 已定位</p></aside></div>
      </template>

      <RouteLibrary v-else-if="view==='routes'" :routes="savedRoutes" :places="places.places" :load-error="routesError" @reload="loadRoutes" @changed="loadRoutes" @import="materialOpen=true" @open-trip="openTrip" @open-places="navigate('places')"/>
      <template v-else-if="view==='inspiration'"><header class="tw-section-heading tw-page-heading"><div><span class="tw-kicker">A LITTLE INSPIRATION</span><h1>旅行，也可以这样开始。</h1><p>挑一种喜欢的方式，填上自己的目的地。</p></div></header><div class="tw-inspiration-grid"><article v-for="item in inspirationTemplates" :key="item.id"><div class="tw-template-cover" :class="'tone-'+item.tone"><span>{{ item.id==='nature'?'🌿':item.id==='food'?'🍜':item.id==='family'?'🪁':'🏛️' }}</span><small>{{ item.days }} DAYS · {{ paceLabels[item.pace] }}</small></div><div><small>{{ item.subtitle }}</small><h2>{{ item.title }}</h2><p>{{ item.description }}</p><div class="tw-template-styles"><span v-for="id in item.styles" :key="id">{{ styles.find(style=>style.id===id)?.name }}</span></div><button class="tw-button secondary" @click="createNew(item.id)">用这个模板开始<ArrowRight :size="14"/></button></div></article></div><p class="tw-template-disclaimer">这些是可编辑的行程结构与出行清单模板，不是社区游记，也不包含虚构的地点、价格或营业信息。</p></template>
    </main>
    <footer class="tw-workspace-footer"><span>WhereToGo · 把灵感带到路上</span><a :href="portalUrl">返回个人门户</a></footer>
  </div>

  <MaterialImporter v-if="materialOpen" :places="places.places" :routes="savedRoutes" @close="materialOpen=false" @saved="materialSaved"/>
  <TripWizard v-if="wizard" :trip="editingTrip" :template="templateId" :busy="busy" :ai-available="aiAvailable" :api-error="error" @close="wizard=false" @save="saveTrip"/>
  <PlaceEditor v-if="placeEditor" :place="editingPlace" :busy="busy" :api-error="error" @close="placeEditor=false" @save="savePlace"/>
  <StopEditor v-if="stopEditor&&trip" :trip="trip" :places="places.places" :stop="editingStop" :date="selectedDay" :busy="busy" :initial-place="initialStopPlace" :api-error="error" @close="stopEditor=false" @save="saveStop"/>
  <TravelModal v-if="draft" title="先看看，再决定。" eyebrow="YOUR ITINERARY DRAFT" wide :locked="busy" :error="error" @close="draft=null"><div class="tw-modal-body"><div class="tw-draft-notes"><p v-for="note in draft.notes" :key="note">{{ note }}</p></div><div class="tw-draft-list"><article v-for="(stop,index) in draft.stops" :key="index"><span>{{ dateLabel(stop.dayDate,{month:'numeric',day:'numeric'}) }}<small>{{ stop.startsAt }}</small></span><div><b>{{ stop.placeName }}</b><p>{{ stop.category }} · {{ stop.durationMinutes }} 分钟</p></div></article></div><p v-if="trip?.stops.length" class="tw-warning">应用后会替换当前旅行的 {{ trip.stops.length }} 项安排。你也可以取消，继续保留原计划。</p></div><footer class="tw-modal-footer"><button class="tw-button secondary" :disabled="busy" @click="draft=null">保留原计划</button><button class="tw-button primary" :disabled="busy" @click="applyDraft">{{ busy?'保存中…':'应用这份草稿' }}</button></footer></TravelModal>
  <TravelModal v-if="notesEditor" title="留给这趟旅行的备忘" eyebrow="TRIP NOTES" :locked="busy" :error="error" @close="notesEditor=false"><form @submit.prevent="saveNotes"><div class="tw-modal-body"><div class="tw-field"><label for="trip-notes">预约、交通、提醒或随手记</label><textarea id="trip-notes" v-model="notesText" rows="10" maxlength="10000" placeholder="想记住的事…"></textarea></div></div><footer class="tw-modal-footer"><button type="button" class="tw-button secondary" :disabled="busy" @click="notesEditor=false">取消</button><button class="tw-button primary" :disabled="busy">保存备忘</button></footer></form></TravelModal>
  <TravelModal v-if="collectionEditor" :title="editingCollectionId?'编辑地点合集':'把喜欢的地方，收在一起。'" eyebrow="PLACE COLLECTION" :locked="busy" :error="error" @close="collectionEditor=false"><form @submit.prevent="saveCollection"><div class="tw-modal-body"><div class="tw-field"><label for="collection-name">合集名称</label><input id="collection-name" v-model="collectionForm.name" required maxlength="100" placeholder="例如：下一次的京都"/></div><div class="tw-form-grid"><div class="tw-field"><label for="collection-color">标记颜色</label><input id="collection-color" v-model="collectionForm.color" type="color"/></div><div class="tw-field"><label for="collection-description">一句话说明</label><input id="collection-description" v-model="collectionForm.description" maxlength="500" placeholder="留给这组合集的备注"/></div></div><div class="tw-field"><label>包含的地点</label><div class="tw-member-list"><label v-for="place in places.places.filter(item=>uuid(item.id))" :key="place.id"><input v-model="collectionForm.placeIds" type="checkbox" :value="place.id"/><span>{{ place.name }}<small>{{ place.city }}</small></span></label><p v-if="!places.places.some(item=>uuid(item.id))" class="tw-hint">先保存一个地点，再加入合集。</p></div></div></div><footer class="tw-modal-footer"><button type="button" class="tw-button secondary" :disabled="busy" @click="collectionEditor=false">取消</button><button class="tw-button primary" :disabled="busy">保存合集</button></footer></form></TravelModal>
  <TravelModal v-if="importOpen" :title="importMode==='trip'?'把旅行计划带过来':'从清单收集想去的地方'" eyebrow="IMPORT YOUR INSPIRATION" wide :locked="busy" :error="error" @close="importOpen=false"><div class="tw-modal-body"><template v-if="importMode==='trip'"><p class="tw-hint">选择 WhereToGo 导出的 JSON，会新建一趟旅行，不会覆盖已有行程。</p><label class="tw-file-drop"><Upload :size="25"/><b>选择行程 JSON 文件</b><small>最多 2MB · 保留日期、安排、预算和出行清单</small><input type="file" accept=".json,application/json" @change="readImport"/></label><div v-if="tripImport" class="tw-trip-summary"><h4>{{ tripImport.input.name }}</h4><p>{{ tripImport.input.destination }} · {{ tripImport.stops.length }} 项安排</p><p>{{ tripImport.input.startsOn }} — {{ tripImport.input.endsOn }}</p></div></template><template v-else><p class="tw-hint">每行一个地点，可用竖线分隔“名称 | 城市 | 分类 | 地址”。也可粘贴公开地图链接，预览后补全名称与城市。这里只解析文本，不抓取链接网页。</p><div class="tw-field"><label for="import-city">默认城市</label><input id="import-city" v-model="importCity" maxlength="120" placeholder="清单中未填写城市时使用"/></div><div class="tw-field"><label for="import-places">地点清单</label><textarea id="import-places" v-model="importText" rows="6" maxlength="50000" placeholder="地点名称 | 城市 | 景点 | 详细地址"></textarea></div><button class="tw-button secondary" :disabled="busy" @click="previewPlaces">预览清单<ArrowRight :size="14"/></button><div v-if="importRows.length" class="tw-import-rows"><p>将导入 {{ importRows.length }} 个地点，请核对名称和城市。</p><div v-for="(item,index) in importRows" :key="index"><span>{{ index+1 }}</span><input v-model="item.name" maxlength="180" aria-label="导入地点名称"/><input v-model="item.city" maxlength="120" aria-label="导入地点城市"/><select v-model="item.category" aria-label="导入地点分类"><option v-for="category in ['景点','美食','咖啡','住宿']" :key="category">{{ category }}</option></select></div></div></template></div><footer class="tw-modal-footer"><button class="tw-button secondary" :disabled="busy" @click="importOpen=false">取消</button><button class="tw-button primary" :disabled="busy||(importMode==='trip'?!tripImport:!importRows.length)" @click="applyImport">{{ busy?'导入中…':'确认导入' }}</button></footer></TravelModal>
  <Transition name="tw-toast"><div v-if="toast" class="tw-toast-message" role="status"><Check :size="16"/>{{ toast }}</div></Transition>
</div>
</template>
